{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='shipping' AND span_name='POST quote' GROUP BY 1,2", "claim": "Shipping's outgoing 'POST quote' client span has p95 about 1470 ms in the abnormal period, versus about 1.5 ms normally."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='quote' AND span_name='POST /getquote' GROUP BY 1,2", "claim": "The quote service's own server span stays at about 0.3 ms, so the delay is before quote receives the request."},
        {"kind": "metric", "sql": "SELECT service_name, metric, max(value) AS max_v, avg(value) AS avg_v FROM abnormal_metrics_sum WHERE metric='k8s.pod.network.errors' AND service_name IN ('shipping','quote') GROUP BY 1,2", "claim": "Pod network error counters for shipping and quote remain zero, so there is no transport-level loss on this path."}
      ]
    }
  ],
  "propagation": [
    {"from": "shipping", "to": "checkout",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('HTTP POST','oteldemo.CheckoutService/PlaceOrder') GROUP BY 1,2", "claim": "Checkout's HTTP POST to shipping and its PlaceOrder server span both sit at about 1.5 s p95, while checkout's own work is about 1.6 ms."}]},
    {"from": "checkout", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST /api/checkout' GROUP BY 1,2", "claim": "Frontend's /api/checkout server span rises to about 1.5 s p95, matching the slow checkout PlaceOrder call."}]},
    {"from": "frontend", "to": "frontend-proxy",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY 1,2", "claim": "Frontend-proxy ingress, the user entry point, shows the same roughly 1.5 s p95 latency."}]}
  ]
}
